#!/usr/bin/env bash
# Create a local virtual environment, activate it, and install the test dependencies.
#
# Source this script so the activation stays in your shell:
#
#   source setup.sh
#
# Run as ./setup.sh, it creates the environment, but the activation ends with the subshell.

# shellcheck source=/dev/null  # .venv/bin/activate is generated by the line itself
python3 -m venv .venv && source .venv/bin/activate \
  && python -m pip install --upgrade pip && pip install -r requirements.txt
